"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[3140],{1206:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>c,contentTitle:()=>a,default:()=>u,frontMatter:()=>r,metadata:()=>o,toc:()=>d});var s=t(4848),i=t(8453);const r={sidebar_position:8},a="8. Determine Funding Strategy",o={id:"AM Steps/Funding",title:"8. Determine Funding Strategy",description:"Defining funding sources is the final step of the asset management process described herein, but ideally, it should be discussed earlier on, alongside budgeting, lifecycle cost analysis, and optimizing investments. Identifying funding strategies early ensures that the long-term financial sustainability of asset systems is incorporated into decision-making and that resources are available to support both capital projects and ongoing asset management training and maintenance programs.",source:"@site/docs/AM Steps/Funding.md",sourceDirName:"AM Steps",slug:"/AM Steps/Funding",permalink:"/AssetManagement/docs/AM Steps/Funding",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:8,frontMatter:{sidebar_position:8},sidebar:"tutorialSidebar",previous:{title:"7.Optimized Investment Strategies",permalink:"/AssetManagement/docs/AM Steps/OptimizeInvestment"},next:{title:"9. Build AM Plan",permalink:"/AssetManagement/docs/AM Steps/BuildPlan"}},c={},d=[];function l(e){const n={a:"a",h1:"h1",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.h1,{id:"8-determine-funding-strategy",children:"8. Determine Funding Strategy"}),"\n",(0,s.jsx)(n.p,{children:"Defining funding sources is the final step of the asset management process described herein, but ideally, it should be discussed earlier on, alongside budgeting, lifecycle cost analysis, and optimizing investments. Identifying funding strategies early ensures that the long-term financial sustainability of asset systems is incorporated into decision-making and that resources are available to support both capital projects and ongoing asset management training and maintenance programs."}),"\n",(0,s.jsxs)(n.p,{children:["Funding for asset management can come from various sources and may support specific capital projects or broader programs aimed at improving asset management, such as training and capacity building. Common funding sources include ",(0,s.jsx)(n.strong,{children:"taxes"}),", ",(0,s.jsx)(n.strong,{children:"user fees"}),", ",(0,s.jsx)(n.strong,{children:"congestion or peak charges"}),", ",(0,s.jsx)(n.strong,{children:"service charges"}),", ",(0,s.jsx)(n.strong,{children:"development charges"}),", ",(0,s.jsx)(n.strong,{children:"grants"}),", ",(0,s.jsx)(n.strong,{children:"interest earned"}),", and ",(0,s.jsx)(n.strong,{children:"proceeds from the disposal of assets"}),". A mix of these can be applied to each system depending on its nature and requirements."]}),"\n",(0,s.jsxs)(n.p,{children:["Different types of infrastructure often rely on distinct funding mechanisms. For example, ",(0,s.jsx)(n.strong,{children:"user fees"})," are frequently used for water systems, where customers are billed based on their water consumption. In contrast, ",(0,s.jsx)(n.strong,{children:"congestion or peak charges"})," are more common in electricity grids and transportation networks, where demand varies significantly throughout the day, and higher fees are applied during peak usage periods. Additionally, ",(0,s.jsx)(n.strong,{children:"capital projects"}),"\u2014such as large-scale infrastructure upgrades \u2014can benefit from ",(0,s.jsx)(n.strong,{children:"grants"})," and ",(0,s.jsx)(n.strong,{children:"development charges"}),"."]}),"\n",(0,s.jsxs)(n.p,{children:["In addition to considering different funding sources, infrastructure systems should also assess the appropriate ",(0,s.jsx)(n.a,{href:"https://imfg.org/uploads/367/2016.11.16_imfg_presentation_gustavocarvalho.pdf",children:"balance between using debt and reserves"}),' for financing large capital projects. Debt financing offers several advantages, such as being easier to secure than increasing taxes or fees, particularly if interests rates are low. It can also be considered fairer from an intergenerational perspective, as future users of the infrastructure contribute to its repayment. Furthermore, debt allows for better alignment between spending and repayment with the asset\u2019s lifecycle, following a "spend-as-you-use" approach. On the other hand, a pay-as-you-go model using reserves, taxes, or fees lead to stronger fiscal discipline by limiting borrowing and ensuring expenditures remain within the system\'s current means.']}),"\n",(0,s.jsxs)(n.p,{children:["Debt practices in infrastructure financing vary significantly across Canadian municipalities, as there is no single overall limit for municipal debt being imposed. Thus, many municipalities are reticent to take on such risk, even if their credit rating is good. In contrast, the United States is generally more comfortable with debt financing, and municipalities and utilities use a variety of different types of bonds to fund infrastructure projects. To create more opportunities for infrastructure funding in Canada, the federal government created the ",(0,s.jsx)(n.a,{href:"https://housing-infrastructure.canada.ca/CIB-BIC/index-eng.html",children:"Canada Infrastructure Bank (CIB)"})," in 2017. It was initially provided with $35 billion in capital used to invest and attract investment from the private sector in infrastructure projects that will benefit the public, support economic growth or support the sustainability of infrastructure in Canada."]})]})}function u(e={}){const{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},8453:(e,n,t)=>{t.d(n,{R:()=>a,x:()=>o});var s=t(6540);const i={},r=s.createContext(i);function a(e){const n=s.useContext(r);return s.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),s.createElement(r.Provider,{value:n},e.children)}}}]);